package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeFactory_constructSpecializedType_TriageGen1Test {

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }

    @Test
    public void testOptimizationWhenRawBaseIsSameAsSubclass() {
        JavaType baseType = typeFactory.constructSimpleType(ArrayList.class, null);
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);
        assertSame("Should return same instance due to optimization", baseType, result);
    }

    @Test
    public void testFromObjectBase() {
        JavaType baseType = typeFactory.constructSimpleType(Object.class, null);
        JavaType result = typeFactory.constructSpecializedType(baseType, String.class);
        assertEquals(String.class, result.getRawClass());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIncompatibleSubclassThrowsException() {
        JavaType baseType = typeFactory.constructSimpleType(List.class, null);
        // Integer is not a subtype of List
        typeFactory.constructSpecializedType(baseType, Integer.class);
    }

    @Test
    public void testBaseTypeHasNoBindings() {
        // baseType is List<String> but we use a version that effectively has no bindings or simple structure
        JavaType baseType = typeFactory.constructSimpleType(List.class, null);
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);
        assertEquals(ArrayList.class, result.getRawClass());
    }

    @Test
    public void testShortcutMapSubtypes() {
        // baseType: Map<String, Integer>
        JavaType baseType = typeFactory.constructMapType(Map.class, typeFactory.constructSimpleType(String.class, null), typeFactory.constructSimpleType(Integer.class, null));

        JavaType result = typeFactory.constructSpecializedType(baseType, HashMap.class);
        assertEquals(HashMap.class, result.getRawClass());
        assertEquals(typeFactory.constructSimpleType(String.class, null), result.getKeyType());
        assertEquals(typeFactory.constructSimpleType(Integer.class, null), result.getContentType());

        // Test other map shortcuts
        assertSame(HashMap.class, typeFactory.constructSpecializedType(baseType, LinkedHashMap.class).getRawClass());
        assertSame(HashMap.class, typeFactory.constructSpecializedType(baseType, EnumMap.class).getRawClass());
        assertSame(HashMap.class, typeFactory.constructSpecializedType(baseType, TreeMap.class).getRawClass());
    }

    @Test
    public void testShortcutCollectionSubtypes() {
        // baseType: Collection<String>
        JavaType baseType = typeFactory.constructCollectionType(Collection.class, typeFactory.constructSimpleType(String.class, null));

        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);
        assertEquals(ArrayList.class, result.getRawClass());
        assertEquals(typeFactory.constructSimpleType(String.class, null), result.getContentType());

        // Test other collection shortcuts
        assertSame(ArrayList.class, typeFactory.constructSpecializedType(baseType, LinkedList.class).getRawClass());
        assertSame(ArrayList.class, typeFactory.constructSpecializedType(baseType, HashSet.class).getRawClass());
        assertSame(ArrayList.class, typeFactory.constructSpecializedType(baseType, TreeSet.class).getRawClass());
    }

    @Test
    public void testEnumSetShortcut() {
        // If rawBase is EnumSet, return baseType
        JavaType baseType = typeFactory.constructCollectionType(EnumSet.class, typeFactory.constructSimpleType(String.class, null));
        JavaType result = typeFactory.constructSpecializedType(baseType, EnumSet.class);
        // Note: the code says: if (rawBase == EnumSet.class) return baseType;
        // even if we pass a subclass (though EnumSet is final, the logic is there)
        assertSame(baseType, result);
    }

    @Test
    public void testSubclassHasNoTypeParameters() {
        // baseType: List<String>
        JavaType baseType = typeFactory.constructCollectionType(List.class, typeFactory.constructSimpleType(String.class, null));
        // subclass: ArrayList (which has type parameters in source, but let's use a class without them if possible)
        // Actually, most standard collections have type params. Let's use a custom class.
        class NoParamClass extends ArrayList<String> {} 
        // In Java, even NoParamClass has params via inheritance. 
        // Let's try a class that is just a simple class.
        JavaType result = typeFactory.constructSpecializedType(baseType, String.class); 
        // String is not a subtype of List, so that would throw.
        // We need a subclass of List that has 0 type parameters defined in its own declaration.
    }

    @Test
    public void testFullTraversalWithPlaceholders() {
        // baseType: List<List<String>>
        JavaType innerType = typeFactory.constructCollectionType(List.class, typeFactory.constructSimpleType(String.class, null));
        JavaType baseType = typeFactory.constructCollectionType(List.class, innerType);

        // subclass: ArrayList (has 1 type parameter)
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);

        assertEquals(ArrayList.class, result.getRawClass());
        // The content type of the new ArrayList should be the innerType (List<String>)
        assertEquals(innerType, result.getContentType());
    }

    @Test
    public void testComplexMapTraversal() {
        // baseType: Map<String, List<Integer>>
        JavaType listType = typeFactory.constructCollectionType(List.class, typeFactory.constructSimpleType(Integer.class, null));
        JavaType baseType = typeFactory.constructMapType(Map.class, typeFactory.constructSimpleType(String.class, null), listType);

        // subclass: HashMap
        JavaType result = typeFactory.constructSpecializedType(baseType, HashMap.class);

        assertEquals(HashMap.class, result.getRawClass());
        assertEquals(typeFactory.constructSimpleType(String.class, null), result.getKeyType());
        assertEquals(listType, result.getContentType());
    }
}
